H.background();
const v = H.plot2d({ xMin: 0.05, xMax: 2 * Math.PI - 0.05, yMin: -2.2, yMax: 2.2 });
v.grid(); v.axes();
const which = Math.round(P.expr);
const eps = 1e-4;
const sec = (x) => { const c = Math.cos(x); return Math.abs(c) < eps ? NaN : 1 / c; };
const tan = (x) => { const c = Math.cos(x); return Math.abs(c) < eps ? NaN : Math.sin(x) / c; };
let orig, simp, origLbl, simpLbl;
if (which <= 1) {
  orig = (x) => { const s = Math.sin(x); return Math.abs(s) < eps ? NaN : (1 - Math.cos(x) * Math.cos(x)) / s; };
  simp = (x) => Math.sin(x);
  origLbl = "(1 - cos^2 x) / sin x"; simpLbl = "sin x";
} else if (which === 2) {
  orig = (x) => { const c = Math.cos(x); return Math.abs(c) < eps ? NaN : Math.sin(x) * sec(x); };
  simp = (x) => tan(x);
  origLbl = "sin x * sec x"; simpLbl = "tan x";
} else {
  orig = (x) => sec(x) * sec(x) - tan(x) * tan(x);
  simp = (x) => 1;
  origLbl = "sec^2 x - tan^2 x"; simpLbl = "1";
}
v.fn(simp, { color: H.colors.good, width: 7 });
v.fn(orig, { color: H.colors.accent2, width: 2.5 });
